mf = create(
    sign=midiutil.FLATS,
    scale=midiutil.MINOR,
    track_names=[
        "percussion",
        "low strings",
        "brass",
        "high strings",
        "choir",
        "french horn",
    ],
)

# General MIDI program changes for Windows MIDI players.
# Signature: addProgramChange(tracknum, channel, time, program)
# Program numbers are zero-based in MIDIUtil.
mf.addProgramChange(1, 1, 0, 48)  # String Ensemble 1
mf.addProgramChange(2, 2, 0, 61)  # Brass Section
mf.addProgramChange(3, 3, 0, 48)  # String Ensemble 1
mf.addProgramChange(4, 4, 0, 52)  # Choir Aahs
mf.addProgramChange(5, 0, 0, 60)  # French Horn

add_notes(mf, 0, PERCUSSION)
add_notes(mf, 1, LOW_STRINGS)
add_notes(mf, 2, BRASS)
add_notes(mf, 3, HIGH_STRINGS)
add_notes(mf, 4, CHOIR)
add_notes(mf, 5, HORN)

# Bar 17 begins at beat 64. Switch to the fast finale.
mf.addTempo(0, 64, 132)

with open("cinematic_dynamic_fast_finale.mid", "wb") as f:
    mf.writeFile(f)

print("Wrote cinematic_dynamic_fast_finale.mid")
